(59915, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_02.blp:20|t |c00F19C88%s|r begins to petrify all players!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60009, 0, 0, 'Tender your souls, mortals! These are the halls of the dead!', 14, 0, 100, 0, 0, 27814, 'FENG_AGGRO'),
(60009, 1, 0, 'Oh great spirit! Grant me the power of the earth!', 14, 0, 100, 0, 0, 27816, 'FENG_PHASE_1'),
(60009, 2, 0, 'Oh exalted one! Through me you shall melt flesh from bone!', 14, 0, 100, 0, 0, 27820, 'FENG_PHASE_2'),
(60009, 3, 0, 'Oh sage of the ages! Instill to me your arcane wisdom!', 14, 0, 100, 0, 0, 27821, 'FENG_PHASE_3'),
(60009, 4, 0, 'Great soul of champions past! Bear to me your shield!', 14, 0, 100, 0, 0, 27817, 'FENG_PHASE_4'),
(60009, 5, 0, 'If they only knew... what horrors await...', 14, 0, 100, 0, 0, 27815, 'FENG_DEATH'),
(60009, 6, 0, 'Ripe for the picking.', 14, 0, 100, 0, 0, 27819, 'FENG_SLAY_1'),
(60009, 6, 1, 'They crumble so easily.', 14, 0, 100, 0, 0, 27818, 'FENG_SLAY_2');
