INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60143, 0, 0, 'It be dyin\' time, now!', 14, 0, 100, 0, 0, 29080, 'GARAJAL_AGGRO'),
(60143, 1, 0, 'OH HO HO! Dat had ta hurt.', 14, 0, 100, 0, 0, 29090, 'GARAJAL_SLAY_1'),
(60143, 1, 1, 'OUCH! Eh-heheheh.', 14, 0, 100, 0, 0, 29091, 'GARAJAL_SLAY_2'),
(60143, 1, 2, 'Spirits be praised!', 14, 0, 100, 0, 0, 29092, 'GARAJAL_SLAY_3'),
(60143, 2, 0, 'Now you done made me angry!', 14, 0, 100, 14, 0, 29087, 'GARAJAL_FRENZY_1'),
(60143, 2, 1, 'Fine, den! Time ta play, friends.', 14, 0, 100, 11, 0, 29088, 'GARAJAL_FRENZY_2'),
(60143, 3, 0, '|TInterface\\Icons\\ability_druid_challangingroar.blp:20|tGara\'jal casts |cFFFF0000|Hspell:117752|h[Frenzy]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(60143, 4, 0, '|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|tGara\'jal summons a Spirit Totem. Use it to |cFFFF0000|Hspell:116161|h[Cross Over]|h|r to the Spirit World!', 41, 0, 100, 0, 0, 0, ''),
(60143, 5, 0, '|TInterface\\Icons\\inv_misc_idol_02.blp:20|tGara\'jal selects random players to become |cFFFF0000|Hspell:122151|h[Voodoo Dolls]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(60143, 6, 0, 'You are a |cFFFF0000|Hspell:122151|h[Voodoo Doll]|h|r! Damage you take is copied to the other Voodoo Dolls in your raid!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60410, 0, 0, 'Sensors online. All cores operating at peak efficiency.', 14, 0, 100, 0, 0, 28544, 'ELEGON_INTRO_1'),
(60410, 1, 0, 'Identification matrix mismatch. Unknown entities detected.', 14, 0, 100, 0, 0, 28545, 'ELEGON_INTRO_2'),
(60410, 2, 0, 'Entering defensive mode.  Disabling output failsafes.', 14, 0, 100, 0, 0, 28534, 'ELEGON_AGGRO'),
(60410, 3, 0, 'Existence ends... I become nothing...', 14, 0, 100, 0, 0, 28535, 'ELEGON_DEATH_1'),
(60410, 4, 0, 'Conduits offline.', 14, 0, 100, 0, 0, 28536, 'ELEGON_A_TO_B_1'),
(60410, 5, 0, 'Approach! Feel the power of the titans!', 14, 0, 100, 0, 0, 28537, 'ELEGON_A_TO_B_2'),
(60410, 6, 0, 'Drawing from reserve power.', 14, 0, 100, 0, 0, 28538, 'ELEGON_B_TO_C_1'),
(60410, 7, 0, 'Energy Vortex ramping down.', 14, 0, 100, 0, 0, 28539, 'ELEGON_C_TO_A_1'),
(60410, 8, 0, 'Redirecting power.', 14, 0, 100, 0, 0, 28540, 'ELEGON_C_TO_A_2'),
(60410, 9, 0, 'Energy Conduits active, draw stable.', 14, 0, 100, 0, 0, 28541, 'ELEGON_C_TO_A_3'),
(60410, 10, 0, 'Engaging total destruction sequence. Good bye.', 14, 0, 100, 0, 0, 28542, 'ELEGON_ENRAGE_HARD'),
(60410, 11, 0, 'Let the energies consume you!', 14, 0, 100, 0, 0, 28543, 'ELEGON_ENRAGE_SOFT'),
(60410, 12, 0, 'The spark of life fades.', 14, 0, 100, 0, 0, 28546, 'ELEGON_SLAY_1'),
(60410, 12, 1, 'What was is no longer.', 14, 0, 100, 0, 0, 28547, 'ELEGON_SLAY_2'),
(60410, 12, 2, 'Countermeasures successful.', 14, 0, 100, 0, 0, 28548, 'ELEGON_SLAY_3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60648, 0, 0, 'The Endless Army will crush the Emperor\'s foes.', 14, 0, 100, 0, 0, 29017, 'will of emperor - TALK_JAN_QIN_XI'),
(60648, 1, 0, 'The Emperor\'s Rage echoes through the hills.', 14, 0, 100, 0, 0, 29018, 'will of emperor - TALK_RAGE'),
(60648, 2, 0, 'The Emperor\'s Strength grips this land with fists of iron.', 14, 0, 100, 0, 0, 29019, 'will of emperor - TALK_STRENGTH'),
(60648, 3, 0, 'The Emperor\'s Courage burns everlasting.', 14, 0, 100, 0, 0, 29020, 'will of emperor - TALK_COURAGE'),
(60648, 4, 0, 'The Emperor\'s Breath is regained.', 14, 0, 100, 0, 0, 29022, 'will of emperor - TALK_TITAN_GAS_START'),
(60648, 5, 0, 'The Emperor\'s Breath abates.', 14, 0, 100, 0, 0, 29021, 'will of emperor - TALK_TITAN_GAS_END'),
(60648, 6, 0, 'The Emperor\'s Will dominates all it beholds.', 14, 0, 100, 0, 0, 29023, 'will of emperor - TALK_DEFEATED'),
(60648, 7, 0, 'Two titanic constructs appear in the large alcoves!', 41, 0, 100, 0, 0, 0, 'will of emperor - TALK_CONSTRUCTS_APPEAR'),
(60648, 8, 0, 'The Emperor\'s Strength appears in the alcoves!', 41, 0, 100, 0, 0, 0, 'will of emperor - TALK_EMPEROR_STRENGTH_ANN'),
(60648, 9, 0, 'The Emperor\'s Courage appears in the alcoves!', 41, 0, 100, 0, 0, 0, 'will of emperor - TALK_EMPEROR_COURAGE_ANN'),
(60648, 10, 0, 'The Ancient Mogu Machine breaks down! |cFFFF0000|Hspell:116779|h[Titan Gas]|h|r floods the room!', 41, 0, 100, 0, 0, 0, 'will of emperor - TALK_TITAN_GAS_ANN'),
(60648, 11, 0, 'The machine hums to life!  Get to the lower level!', 41, 0, 100, 0, 0, 0, 'will of emperor - TALK_TO_LOWER_LEVEL');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60701, 0, 0, 'Soon you will understand why my subjects fear the shadows!', 14, 0, 100, 0, 0, 27958, 'ZIAN_AGGRO'),
(60701, 1, 0, 'The darkness... surrounds me!', 14, 0, 100, 0, 0, 27959, 'ZIAN_DEFEATED'),
(60701, 2, 0, 'I sense... courage. Willpower. Light. Hmph. That will not do.', 14, 0, 100, 0, 0, 27960, 'ZIAN_INTRO'),
(60701, 3, 0, 'Fall into darkness.', 14, 0, 100, 0, 0, 27961, 'ZIAN_SLAY_1'),
(60701, 3, 1, 'The shadows consume you.', 14, 0, 100, 0, 0, 27962, 'ZIAN_SLAY_2'),
(60701, 3, 2, 'THIS is what it means to face an emperor!', 14, 0, 100, 0, 0, 27963, 'ZIAN_SLAY_3'),
(60701, 4, 0, 'The darkness comes for you, and with it, death.', 14, 0, 100, 0, 0, 27964, 'ZIAN_SPELL'),
(60701, 5, 0, '|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s casts |cFFFF0000|Hspell:117506|h[Undying Shadows]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60708, 0, 0, 'You have angered the emperor! THE SENTENCE IS DEATH!', 14, 0, 100, 0, 0, 28069, 'MENG_AGGRO'),
(60708, 1, 0, 'The sentence... was to be... yours..', 14, 0, 100, 0, 0, 28070, 'MENG_DEFEATED_CRAZED'),
(60708, 2, 0, 'I... I don\'t want to die!', 14, 0, 100, 0, 0, 28071, 'MENG_DEFEATED_COWARDICE'),
(60708, 3, 0, 'Who dares summon Emperor Meng, most majestic of mighty monarchs?!', 14, 0, 100, 0, 0, 28072, 'MENG_INTRO'),
(60708, 4, 0, 'Like rice stalks before the blade, all fall before me!', 14, 0, 100, 0, 0, 28073, 'MENG_SLAY_1'),
(60708, 4, 1, 'None may stand against the imperial majesty of MENG!', 14, 0, 100, 0, 0, 28074, 'MENG_SLAY_2'),
(60708, 4, 2, 'Don\'t bleed on me! Filthy! Disease!', 14, 0, 100, 0, 0, 28075, 'MENG_SLAY_3'),
(60708, 4, 3, 'You made me do it!', 14, 0, 100, 0, 0, 28076, 'MENG_SLAY_4'),
(60708, 5, 0, 'Slaughter yourselves for my amusement!', 14, 0, 100, 0, 0, 28077, 'MENG_SPELL_1'),
(60708, 5, 1, 'Enemies... everywhere! Kill! Kill them all!', 14, 0, 100, 0, 0, 28078, 'MENG_SPELL_2'),
(60708, 6, 0, '|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s casts |cFFFF0000|Hspell:117708|h[Maddening Shout]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60709, 0, 0, 'I will crush you, in body AND spirit.', 14, 0, 100, 0, 0, 28057, 'QIANG_AGGRO'),
(60709, 1, 0, 'I... cannot be... defeated..', 14, 0, 100, 0, 0, 28058, 'QIANG_DEFEATED'),
(60709, 2, 0, 'My armies are endless, my power, unmatched.', 14, 0, 100, 0, 0, 28059, 'QIANG_INTRO'),
(60709, 3, 0, 'My tactics are unbeatable.', 14, 0, 100, 0, 0, 28060, 'QIANG_SLAY_1'),
(60709, 3, 1, 'Another victory.', 14, 0, 100, 0, 0, 28061, 'QIANG_SLAY_2'),
(60709, 3, 2, 'The emperor rules ALL!', 14, 0, 100, 0, 0, 28062, 'QIANG_SLAY_3'),
(60709, 4, 0, 'Soldiers! Crush their flank!', 14, 0, 100, 0, 0, 28063, 'QIANG_SPELL_1'),
(60709, 4, 1, 'Flanking attack! March into battle!', 14, 0, 100, 0, 0, 28064, 'QIANG_SPELL_2'),
(60709, 5, 0, '|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s casts |cFFFF0000|Hspell:117910|h[Flanking Orders]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(60710, 0, 0, 'You\'ll see your mistake soon enough!', 14, 0, 100, 0, 0, 28109, 'SUBETAI_AGGRO'),
(60710, 1, 0, 'I am... bested.', 14, 0, 100, 0, 0, 28110, 'SUBETAI_DEFEATED'),
(60710, 2, 0, 'Bandits and emperors; we both take what we want!', 14, 0, 100, 0, 0, 28111, 'SUBETAI_INTRO'),
(60710, 3, 0, 'You were too slow!', 14, 0, 100, 0, 0, 28112, 'SUBETAI_SLAY_1'),
(60710, 3, 1, 'I am too quick, too clever.', 14, 0, 100, 0, 0, 28113, 'SUBETAI_SLAY_2'),
(60710, 3, 2, 'You stood no chance!', 14, 0, 100, 0, 0, 28114, 'SUBETAI_SLAY_3'),
(60710, 4, 0, 'All that is yours? Mine!', 14, 0, 100, 0, 0, 28115, 'SUBETAI_SPELL_1'),
(60710, 4, 1, 'There is nothing I cannot take!', 14, 0, 100, 0, 0, 28116, 'SUBETAI_SPELL_2'),
(60710, 5, 0, '|TInterface\\Icons\\ability_rogue_dismantle.blp:20|t%s casts |cFFFF0000|Hspell:118047|h[Pillage]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(61140, 0, 0, 'Bah! Bested by de likes of you! What a shame for a Zandalari Priest ta endure.', 14, 0, 100, 0, 0, 29082, 'GARAJAL_DEATH_1'),
(61140, 0, 1, 'But it ain\'t no ting. Take your trinkets; you\'ll be needin\' dem.', 14, 0, 100, 0, 0, 29083, 'GARAJAL_DEATH_2'),
(61140, 0, 2, 'I be goin\' now; time ta find a new home for me soul.', 14, 0, 100, 0, 0, 29084, 'GARAJAL_DEATH_3'),
(61140, 0, 3, 'Death be a doorway, an\' time a window; I\'ll be back! AH-HAHAHAHAHAH!', 14, 0, 100, 0, 0, 29085, 'GARAJAL_DEATH_4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(61348, 0, 0, 'The ancient vaults of the mogu, untouched by time for thousands of years, who knows what secrets await?', 12, 0, 100, 0, 0, 30198, 'LOREWALKER_CHO_INTRO_1'),
(61348, 1, 0, 'Many young Pandaren warriors have vanished into this...tomb. Have your wits about you.', 12, 0, 100, 0, 0, 30199, 'LOREWALKER_CHO_INTRO_2'),
(61348, 2, 0, 'The large Quilen seem to be guarding that door. Tread carefully, lest you wake them.', 12, 0, 100, 0, 0, 30179, 'LOREWALKER_CHO_DOGS'),
(61348, 3, 0, 'That was close!', 14, 0, 100, 0, 0, 30180, 'LOREWALKER_CHO_DOGS_DIE'),
(61348, 4, 0, 'The door mechanism seems to have activated with the demise of the guardians. I fear what we may find within.', 12, 0, 100, 0, 0, 30181, 'LOREWALKER_CHO_DOGS_DOOR_EVENT'),
(61348, 5, 0, 'We seem to have awakened a spirit of some kind.', 12, 0, 100, 0, 0, 30193, 'LOREWALKER_CHO_FENG_EVENT_1'),
(61348, 6, 0, 'So the stories were true...', 12, 0, 100, 0, 0, 30194, 'LOREWALKER_CHO_FENG_EVENT_2'),
(61348, 7, 0, 'We have disturbed what should not have been disturbed. He cannot be free to escape this prison! You must destroy him!', 12, 0, 100, 0, 0, 30195, 'LOREWALKER_CHO_FENG_EVENT_3'),
(61348, 8, 0, 'Feng the Accursed was betrayed by four emperors of the mogu, his body destroyed each time, only to rise again.', 12, 0, 100, 0, 0, 30196, 'LOREWALKER_CHO_FENG_PAST_EVENT_1'),
(61348, 9, 0, 'This is not the last we have seen of Feng...', 12, 0, 100, 0, 0, 30197, 'LOREWALKER_CHO_FENG_PAST_EVENT_2'),
(61348, 10, 0, 'The Zandalari, ancient allies of the mogu! They must seek the legendary weapon within the depths of the Vaults!', 12, 0, 100, 0, 0, 30209, 'LOREWALKER_CHO_GARAJAL_EVENT_1'),
(61348, 11, 0, 'I am sorry I did not tell you earlier! These vaults house a weapon of unimaginable power! Stop them!', 12, 0, 100, 0, 0, 30208, 'LOREWALKER_CHO_GARAJAL_EVENT_2'),
(61348, 12, 0, 'I will stay behind and investigate this dais further...', 12, 0, 100, 0, 0, 30210, 'LOREWALKER_CHO_GARAJAL_EVENT_3'),
(61348, 13, 0, 'Ah, the ancient Vaults of the Kings of Mogu\'shan. What might this button do...?', 12, 0, 100, 0, 0, 30176, 'LOREWALKER_CHO_SPIRIT_KINGS_EVENT_1'),
(61348, 14, 0, 'Look here! It\'s the history of Zian of the Endless Shadow, a powerful sorcerer who kept the kingdoms in check through terror and darkness.', 12, 0, 100, 0, 0, 30207, 'LOREWALKER_CHO_SPIRIT_KINGS_EVENT_ZIAN'),
(61348, 15, 0, 'This looks to be the record of Qiang the Merciless, a great conqueror who ruled his vassals with an iron fist!', 12, 0, 100, 0, 0, 31529, 'LOREWALKER_CHO_SPIRIT_KINGS_EVENT_QUIANG'),
(61348, 16, 0, 'I\'ve heard tales of this one: Subetai the Swift, well known as a masterful archer and genius thief. He stole from the rich, and kept everything for himself.', 12, 0, 100, 0, 0, 30177, 'LOREWALKER_CHO_SPIRIT_KINGS_EVENT_SUBETAI'),
(61348, 17, 0, 'What is this? I\'ve heard nothing of this emperor. Meng the Demented? According to these texts, Meng was the most foul and maniacal ruler to ever abuse the imperial throne.', 12, 0, 100, 0, 0, 31528, 'LOREWALKER_CHO_SPIRIT_KINGS_EVENT_MENG'),
(61348, 18, 0, 'Heroes! You\'re alive. I brought help.', 14, 0, 100, 0, 0, 38147, '');
